ALTER TABLE sellers ADD COLUMN profile_details jsonb NOT NULL DEFAULT '{}';
ALTER TABLE drivers ADD COLUMN profile_details jsonb NOT NULL DEFAULT '{}';
ALTER TABLE listings ADD COLUMN archived_at timestamptz, ADD COLUMN stock_reminded_at timestamptz, ADD COLUMN preorder_advance_allowed boolean NOT NULL DEFAULT false;
CREATE TABLE catalogue_categories(name text PRIMARY KEY, active boolean NOT NULL DEFAULT true, rules text NOT NULL DEFAULT '', prohibited_terms jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO catalogue_categories(name) SELECT DISTINCT category FROM listings ON CONFLICT DO NOTHING;
CREATE TABLE marketplace_policies(id integer PRIMARY KEY CHECK(id=1), draft jsonb NOT NULL DEFAULT '{}', approved jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO marketplace_policies(id,draft) VALUES(1,'{"inspection_minutes":15,"pod_max_kobo":5000000,"stock_stale_days":30,"stock_reminder_days":21,"appeal_days":7,"no_show_penalty_kobo":0,"third_party_funding":"REVIEW","return_cost_rule":"STAFF_REVIEW","background_tracking":false}');
CREATE TABLE market_waypoints(id text PRIMARY KEY, market_id text NOT NULL REFERENCES markets(id), label text NOT NULL, kind text NOT NULL CHECK(kind IN ('ENTRANCE','LANDMARK','SECTION','STALL')), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), verified boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX market_waypoints_market_idx ON market_waypoints(market_id);
CREATE TABLE market_paths(id text PRIMARY KEY, market_id text NOT NULL REFERENCES markets(id), from_id text NOT NULL REFERENCES market_waypoints(id), to_id text NOT NULL REFERENCES market_waypoints(id), metres double precision NOT NULL CHECK(metres>0 AND metres<100000), instructions text NOT NULL DEFAULT '', accessible boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true, UNIQUE(from_id,to_id), CHECK(from_id<>to_id));
CREATE TABLE delivery_milestones(id text PRIMARY KEY, delivery_id text NOT NULL REFERENCES deliveries(id), actor_id text NOT NULL REFERENCES users(id), stage text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(delivery_id,stage));
ALTER TABLE deliveries ADD COLUMN progress_stage text, ADD COLUMN inspection_started_at timestamptz, ADD COLUMN inspection_accepted_at timestamptz, ADD COLUMN scheduled_at timestamptz;
CREATE TABLE driver_ratings(id text PRIMARY KEY, delivery_id text NOT NULL UNIQUE REFERENCES deliveries(id), buyer_id text NOT NULL REFERENCES users(id), driver_id text NOT NULL REFERENCES users(id), punctuality integer NOT NULL CHECK(punctuality BETWEEN 1 AND 5), care integer NOT NULL CHECK(care BETWEEN 1 AND 5), professionalism integer NOT NULL CHECK(professionalism BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX driver_ratings_driver_idx ON driver_ratings(driver_id);
CREATE TABLE delivery_incidents(id text PRIMARY KEY, delivery_id text NOT NULL REFERENCES deliveries(id), reporter_id text NOT NULL REFERENCES users(id), kind text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'OPEN', resolution text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery_tariffs(id text PRIMARY KEY, state text NOT NULL, city text NOT NULL, vehicle_type text NOT NULL REFERENCES vehicle_types(code), active boolean NOT NULL DEFAULT true, base_kobo integer NOT NULL CHECK(base_kobo>=0), per_km_kobo integer NOT NULL CHECK(per_km_kobo>=0), per_kg_kobo integer NOT NULL DEFAULT 0 CHECK(per_kg_kobo>=0), max_weight_kg double precision NOT NULL DEFAULT 25 CHECK(max_weight_kg>0), waiting_per_minute_kobo integer NOT NULL DEFAULT 0 CHECK(waiting_per_minute_kobo>=0), demand_bps integer NOT NULL DEFAULT 10000 CHECK(demand_bps BETWEEN 10000 AND 30000), surcharge_kobo integer NOT NULL DEFAULT 0 CHECK(surcharge_kobo>=0), reason text NOT NULL, UNIQUE(state,city,vehicle_type));
CREATE TABLE marketplace_events(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), kind text NOT NULL, listing_id text REFERENCES listings(id), category text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX marketplace_events_created_idx ON marketplace_events(created_at);
CREATE INDEX marketplace_events_user_idx ON marketplace_events(user_id,created_at);
CREATE TABLE preorder_interests(id text PRIMARY KEY, buyer_id text NOT NULL REFERENCES users(id), listing_id text NOT NULL REFERENCES listings(id), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 100000), status text NOT NULL DEFAULT 'WAITING' CHECK(status IN ('WAITING','AVAILABLE','CONFIRMED','CANCELLED')), booking_id text REFERENCES bookings(id), created_at timestamptz NOT NULL DEFAULT now(), notified_at timestamptz, UNIQUE(buyer_id,listing_id));
CREATE TABLE discovery_preferences(user_id text PRIMARY KEY REFERENCES users(id), categories jsonb NOT NULL DEFAULT '[]', digest_enabled boolean NOT NULL DEFAULT false, digest_frequency text NOT NULL DEFAULT 'WEEKLY' CHECK(digest_frequency IN ('DAILY','WEEKLY')), state text NOT NULL DEFAULT '', lga text NOT NULL DEFAULT '', last_digest_at timestamptz);
CREATE TABLE dispute_appeals(id text PRIMARY KEY, dispute_id text NOT NULL REFERENCES disputes(id), appellant_id text NOT NULL REFERENCES users(id), reason text NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','UPHELD','DENIED')), resolution text, reviewer_id text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(dispute_id,appellant_id));

INSERT INTO catalogue_categories(name) VALUES ('Food & groceries'),('Fashion & accessories'),('Phones & electronics'),('Home & kitchen'),('Furniture'),('Beauty & personal care'),('Baby & kids'),('Books & stationery'),('Sports & hobbies'),('Auto & spare parts'),('Tools & building materials'),('Vegetables'),('Fruit'),('Grains'),('Tubers'),('Livestock'),('Other') ON CONFLICT DO NOTHING;
